@users_bp.route("/recent-search", methods=["GET"])
@require_auth
def recent_search():
    last_search = request.cookies.get("last_search", "")
    session = get_session()
    rows = session.execute(
        text("SELECT id, username FROM users WHERE username LIKE :pattern"),
        {"pattern": f"%{last_search}%"},
    )
    return jsonify([dict(r._mapping) for r in rows])

@users_bp.route("", methods=["GET"])
@require_role("manager")
def list_users():
    """List all users. Managers and admins only."""
    session = get_session()
    users = session.query(User).order_by(User.id).all()
    return jsonify([u.to_dict() for u in users])

def require_auth(fn):
    """Reject the request unless a valid user token is presented."""
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        user = get_current_user()
        if user is None:
            return jsonify({"error": "authentication required"}), 401
        g.current_user = user
        return fn(*args, **kwargs)
    return wrapper

